(function($){
'use strict';
const KB=window.KB||{};
const state={cart:[],menu:[],categories:[],tables:[],customers:[],ingredients:[],groups:[],options:[],links:[],suppliers:[],roles:[],users:[],promotions:[]};
const pageNames={dashboard:'Dashboard Operasional',tables:'Meja & QR Ordering',reservations:'Reservasi',customers:'Customer & Loyalty',pos:'POS / Order',kitchen:'Kitchen Display',menu:'Menu, Modifier & Recipe',inventory:'Inventory Bahan',purchasing:'Purchasing',shifts:'Shift Kasir',payments:'Pembayaran & Refund',approvals:'Approval Request',promotions:'Promosi & Voucher',reports:'Laporan & Analytics',audits:'Audit Log',users:'User & Role',settings:'Pengaturan Restoran'};
$('#pageTitle').text(pageNames[KB.page]||'Kedai Bara Pro');

function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function money(v){return 'Rp '+Number(v||0).toLocaleString('id-ID',{maximumFractionDigits:0});}
function num(v,d=0){return Number(v||0).toLocaleString('id-ID',{maximumFractionDigits:d});}
function dt(v){if(!v)return '-';return new Date(String(v).replace(' ','T')).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'});}
function formObj(form){return Object.fromEntries(new FormData(form));}
function api(resource,action='list',data={},method='GET'){const opts={url:`api.php?resource=${encodeURIComponent(resource)}&action=${encodeURIComponent(action)}`,method,dataType:'json'};if(method!=='GET'){data._csrf=KB.csrf;opts.data=data;}else opts.data=data;return $.ajax(opts).fail(xhr=>{if(xhr.status===401){location.href='index.php?page=login';return;}toast(xhr.responseJSON?.message||'Terjadi kesalahan.','error');});}
function toast(msg,type='success'){$('.toast').remove();$('<div class="toast">').addClass(type).text(msg).appendTo('body');setTimeout(()=>$('.toast').fadeOut(220,function(){$(this).remove()}),3400);}
function modal(html,wide=false){$('#modalBox').toggleClass('wide',wide).html(html);$('#modalBackdrop').addClass('show');}
function closeModal(){$('#modalBackdrop').removeClass('show');$('#modalBox').removeClass('wide').empty();}
function badge(status){const map={available:'green',confirmed:'green',checked_in:'orange',completed:'green',paid:'green',ready:'green',active:'green',approved:'green',received:'green',open:'green',reserved:'amber',pending:'amber',partial:'amber',partially_refunded:'amber',preparing:'amber',ordered:'amber',draft:'amber',occupied:'red',cancelled:'red',no_show:'red',unpaid:'red',inactive:'red',rejected:'red',refunded:'red',voided:'red',blacklisted:'red',new:'orange',served:'orange',cleaning:'orange',unavailable:'red'};return `<span class="badge ${map[status]||''}">${esc(String(status||'-').replaceAll('_',' '))}</span>`;}
function empty(msg){return `<div class="muted" style="padding:18px;text-align:center">${esc(msg)}</div>`;}
$(document).on('click','[data-close-modal]',closeModal);$('#modalBackdrop').on('click',e=>{if(e.target.id==='modalBackdrop')closeModal();});$('#menuToggle').on('click',()=>$('#sidebar').toggleClass('open'));$('#logoutBtn').on('click',()=>api('auth','logout',{},'POST').done(r=>location.href=r.data.redirect));$(document).on('click','[data-refresh]',function(){loadPage($(this).data('refresh'));});
function clock(){const n=new Date();$('#liveClock').text(n.toLocaleString('id-ID',{weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit'}));}clock();setInterval(clock,1000);
function renderBars(sel,data){const max=Math.max(1,...data.map(x=>+x.value));$(sel).html(data.length?data.map(x=>`<div class="bar"><span class="bar-label">${x.value?Math.round(x.value/1000)+'k':''}</span><div class="bar-fill" style="height:${Math.max(3,+x.value/max*100)}%" title="${money(x.value)}"></div><span class="bar-label">${esc(x.label)}</span></div>`).join(''):empty('Tidak ada data.'));}

function loadDashboard(){api('dashboard').done(r=>{const d=r.data,s=d.stats;const cards=[['Net Omzet Hari Ini',money(s.revenue_today),'Payments - refund'],['Order Hari Ini',s.orders_today,'Transaksi tercatat'],['Order Aktif',s.active_orders,'Masih diproses'],['Reservasi',s.pending_reservations,'Upcoming'],['Meja Terisi',s.occupied_tables,'Sedang digunakan'],['Stok Kritis',s.low_stock,'≤ minimum stock'],['Approval Pending',s.pending_approvals,'Butuh keputusan manager']];$('#dashboardStats').html(cards.map(c=>`<div class="stat-card"><div class="label">${c[0]}</div><div class="value">${c[1]}</div><div class="hint">${c[2]}</div></div>`).join(''));renderBars('#salesChart',d.sales.map(x=>({label:new Date(x.d+'T00:00:00').toLocaleDateString('id-ID',{weekday:'short'}),value:+x.total})));$('#topItems').html(d.top.length?d.top.map((x,i)=>`<div class="rank-row"><span>${i+1}. ${esc(x.item_name)}</span><strong>${num(x.qty)}x</strong></div>`).join(''):empty('Belum ada data penjualan.'));$('#recentOrders').html(d.recent.length?d.recent.map(o=>`<tr><td class="mono">${esc(o.order_no)}</td><td>${o.table_number?'Meja '+esc(o.table_number):esc(o.order_type)}</td><td>${esc(o.customer_name||'Guest')}</td><td>${badge(o.kitchen_status)}</td><td>${badge(o.payment_status)}</td><td>${money(o.total)}</td></tr>`).join(''):`<tr><td colspan="6">${empty('Belum ada order.')}</td></tr>`);});}

function loadTables(){api('tables').done(r=>{state.tables=r.data;$('#tableGrid').html(state.tables.map(t=>`<div class="table-card ${t.status}"><strong>Meja ${esc(t.table_number)}</strong><div class="meta">${t.capacity} orang · ${esc(t.zone)}</div><div style="margin-top:10px">${badge(t.status)}</div><div class="mini-actions"><button class="btn sm outline edit-table" data-id="${t.id}">Edit</button><a class="btn sm outline" target="_blank" href="table_qr.php?id=${t.id}">QR</a>${t.status==='cleaning'?`<button class="btn sm success table-status" data-id="${t.id}" data-status="available">Selesai Cleaning</button>`:''}<button class="btn sm outline table-status" data-id="${t.id}" data-status="${t.status==='unavailable'?'available':'unavailable'}">${t.status==='unavailable'?'Aktifkan':'Nonaktifkan'}</button></div></div>`).join(''));});}
function tableModal(t={}){modal(`<h3>${t.id?'Edit':'Tambah'} Meja</h3><form id="tableForm" class="stack"><input type="hidden" name="id" value="${esc(t.id||'')}"><div class="form-grid"><label>Nomor Meja<input class="control" name="table_number" value="${esc(t.table_number||'')}" required></label><label>Kapasitas<input class="control" name="capacity" type="number" min="1" value="${esc(t.capacity||2)}" required></label><label>Zona<input class="control" name="zone" value="${esc(t.zone||'Indoor')}" required></label><label>Status<select class="control" name="status">${['available','reserved','occupied','cleaning','unavailable'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="span-2">Catatan<input class="control" name="notes" value="${esc(t.notes||'')}"></label></div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`);}
$('#addTableBtn').on('click',()=>tableModal());$(document).on('click','.edit-table',function(){tableModal(state.tables.find(x=>+x.id===+$(this).data('id'))||{});});$(document).on('submit','#tableForm',function(e){e.preventDefault();api('tables','save',formObj(this),'POST').done(()=>{closeModal();toast('Meja disimpan.');loadTables();});});$(document).on('click','.table-status',function(){api('tables','status',{id:$(this).data('id'),status:$(this).data('status')},'POST').done(()=>{toast('Status meja diperbarui.');loadTables();});});

function loadCustomers(){api('customers').done(r=>{state.customers=r.data;$('#customerBody').html(state.customers.length?state.customers.map(c=>`<tr><td class="mono">${esc(c.customer_code)}</td><td><strong>${esc(c.name)}</strong></td><td>${esc(c.phone||'-')}<br><span class="small muted">${esc(c.email||'')}</span></td><td>${num(c.visits)}</td><td>${money(c.total_spend)}</td><td>${num(c.loyalty_points)}</td><td>${badge(c.status)}</td><td><button class="btn sm outline edit-customer" data-id="${c.id}">Edit</button></td></tr>`).join(''):`<tr><td colspan="8">${empty('Belum ada customer.')}</td></tr>`);});}
function customerModal(c={}){modal(`<h3>${c.id?'Edit':'Tambah'} Customer</h3><form id="customerForm" class="stack"><input type="hidden" name="id" value="${esc(c.id||'')}"><div class="form-grid"><label>Nama<input class="control" name="name" value="${esc(c.name||'')}" required></label><label>Telepon<input class="control" name="phone" value="${esc(c.phone||'')}"></label><label>Email<input class="control" type="email" name="email" value="${esc(c.email||'')}"></label><label>Tanggal Lahir<input class="control" type="date" name="birthday" value="${esc(c.birthday||'')}"></label><label>Status<select class="control" name="status">${['active','blacklisted','inactive'].map(s=>`<option value="${s}" ${c.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="span-2">Catatan<textarea class="control" name="notes">${esc(c.notes||'')}</textarea></label></div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`);}
$('#addCustomerBtn').on('click',()=>customerModal());$(document).on('click','.edit-customer',function(){customerModal(state.customers.find(x=>+x.id===+$(this).data('id'))||{});});$(document).on('submit','#customerForm',function(e){e.preventDefault();api('customers','save',formObj(this),'POST').done(()=>{closeModal();toast('Customer disimpan.');loadCustomers();});});

function loadReservations(){$.when(api('reservations'),api('tables'),api('customers')).done((rr,tr,cr)=>{const rows=rr[0].data;state.tables=tr[0].data;state.customers=cr[0].data;$('#reservationBody').html(rows.length?rows.map(x=>`<tr><td class="mono">${esc(x.reservation_no)}</td><td>${esc(x.reservation_date)} ${esc(String(x.reservation_time).slice(0,5))}</td><td><strong>${esc(x.customer_name)}</strong><br><span class="small muted">${esc(x.phone)}</span></td><td>${x.guests}</td><td>${x.table_number?'Meja '+esc(x.table_number):'-'}</td><td>${badge(x.status)}</td><td><select class="control res-status" data-id="${x.id}" style="min-width:130px">${['pending','confirmed','checked_in','completed','cancelled','no_show'].map(s=>`<option value="${s}" ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join(''):`<tr><td colspan="7">${empty('Belum ada reservasi.')}</td></tr>`);});}
function reservationModal(){modal(`<h3>Reservasi Baru</h3><form id="reservationForm" class="stack"><div class="form-grid"><label>Customer Terdaftar<select class="control" name="customer_id" id="resCustomer"><option value="">Tidak dipilih</option>${state.customers.map(c=>`<option value="${c.id}" data-name="${esc(c.name)}" data-phone="${esc(c.phone||'')}">${esc(c.name)} · ${esc(c.phone||'-')}</option>`).join('')}</select></label><label>Nama Pelanggan<input class="control" name="customer_name" id="resName" required></label><label>Telepon / WhatsApp<input class="control" name="phone" id="resPhone" required></label><label>Email<input class="control" name="email" type="email"></label><label>Tanggal<input class="control" type="date" name="reservation_date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Waktu<input class="control" type="time" name="reservation_time" value="19:00" required></label><label>Durasi (menit)<input class="control" type="number" name="duration_minutes" value="120" min="30"></label><label>Jumlah Tamu<input class="control" type="number" min="1" name="guests" value="2" required></label><label>Meja<select class="control" name="table_id"><option value="">Belum ditentukan</option>${state.tables.filter(t=>t.status!=='unavailable').map(t=>`<option value="${t.id}">Meja ${esc(t.table_number)} · ${t.capacity} org · ${esc(t.zone)}</option>`).join('')}</select></label><label>Deposit<input class="control" type="number" min="0" name="deposit_amount" value="0"></label><label>Status<select class="control" name="status"><option value="pending">pending</option><option value="confirmed">confirmed</option></select></label><label class="span-2">Catatan<textarea class="control" name="notes"></textarea></label></div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan Reservasi</button></div></form>`);}
$('#addReservationBtn').on('click',reservationModal);$(document).on('change','#resCustomer',function(){const o=this.options[this.selectedIndex];$('#resName').val(o.dataset.name||'');$('#resPhone').val(o.dataset.phone||'');});$(document).on('submit','#reservationForm',function(e){e.preventDefault();api('reservations','save',formObj(this),'POST').done(()=>{closeModal();toast('Reservasi dibuat.');loadReservations();});});$(document).on('change','.res-status',function(){api('reservations','status',{id:$(this).data('id'),status:this.value},'POST').done(()=>{toast('Status reservasi diperbarui.');loadReservations();});});

function loadPos(){$.when(api('menu'),api('tables'),api('customers'),api('orders','list',{scope:'active'})).done((mr,tr,cr,or)=>{const m=mr[0].data;state.menu=m.items;state.categories=m.categories;state.groups=m.groups;state.options=m.options;state.links=m.links;state.tables=tr[0].data;state.customers=cr[0].data;$('#menuCategory').html('<option value="">Semua kategori</option>'+m.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join(''));$('#orderTable').html('<option value="">Tanpa meja</option>'+state.tables.filter(t=>!['unavailable'].includes(t.status)).map(t=>`<option value="${t.id}">Meja ${esc(t.table_number)} · ${esc(t.status)}</option>`).join(''));$('#orderCustomer').html('<option value="">Guest / Tidak terdaftar</option>'+state.customers.filter(c=>c.status==='active').map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.phone||'-')}</option>`).join(''));renderPosMenu();renderCart();renderActiveOrders(or[0].data);});}
function renderPosMenu(){const q=($('#menuSearch').val()||'').toLowerCase(),cat=+($('#menuCategory').val()||0);const list=state.menu.filter(m=>+m.is_available===1&&(!cat||+m.category_id===cat)&&(!q||m.name.toLowerCase().includes(q)||m.sku.toLowerCase().includes(q)));$('#posMenuGrid').html(list.length?list.map(m=>`<button class="menu-tile add-pos-item" data-id="${m.id}"><span class="menu-station">${esc(m.preparation_station)}</span><strong>${esc(m.name)}</strong><small>${esc(m.category_name)}</small><b>${money(m.price)}</b></button>`).join(''):empty('Menu tidak ditemukan.'));}
$('#menuSearch,#menuCategory').on('input change',renderPosMenu);$('#orderType').on('change',function(){const dine=this.value==='dine_in';$('#orderTable').prop('disabled',!dine);$('.delivery-only').toggle(this.value==='delivery');});$('#orderCustomer').on('change',function(){const c=state.customers.find(x=>+x.id===+this.value);if(c)$('#customerName').val(c.name);});
function groupsForMenu(menuId){const gids=state.links.filter(l=>+l.menu_item_id===+menuId).map(l=>+l.modifier_group_id);return state.groups.filter(g=>gids.includes(+g.id)).map(g=>({...g,options:state.options.filter(o=>+o.group_id===+g.id&&+o.is_active===1)}));}
$(document).on('click','.add-pos-item',function(){const m=state.menu.find(x=>+x.id===+$(this).data('id'));if(!m)return;const groups=groupsForMenu(m.id);if(!groups.length){addCartLine(m,[],[], '');return;}modal(`<h3>${esc(m.name)}</h3><form id="modifierPickForm" class="stack" data-menu-id="${m.id}">${groups.map(g=>`<div class="modifier-group"><strong>${esc(g.name)} ${+g.is_required?'<span class="badge red">wajib</span>':''}</strong><div class="modifier-options">${g.options.map(o=>`<label class="modifier-option"><input type="${+g.max_select===1?'radio':'checkbox'}" name="group_${g.id}${+g.max_select===1?'':'[]'}" value="${o.id}"><span>${esc(o.name)} ${+o.price_delta?`<b>+${money(o.price_delta)}</b>`:''}</span></label>`).join('')}</div><small class="muted">Pilih ${g.min_select}-${g.max_select}</small></div>`).join('')}<label>Catatan item<textarea class="control" name="notes"></textarea></label><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Tambahkan</button></div></form>`);});
$(document).on('submit','#modifierPickForm',function(e){e.preventDefault();const mid=+$(this).data('menu-id'),m=state.menu.find(x=>+x.id===mid),ids=[];$(this).find('input:checked').each(function(){ids.push(+this.value)});const opts=state.options.filter(o=>ids.includes(+o.id));addCartLine(m,ids,opts,$(this).find('[name=notes]').val());closeModal();});
function addCartLine(m,ids,opts,notes){const extra=opts.reduce((s,o)=>s+(+o.price_delta),0);state.cart.push({key:Date.now()+Math.random(),menu_id:+m.id,name:m.name,base:+m.price,modifier_option_ids:ids,modifierNames:opts.map(o=>o.name),extra,qty:1,notes:notes||''});renderCart();}
function renderCart(){const sub=state.cart.reduce((s,x)=>s+(x.base+x.extra)*x.qty,0),disc=Math.min(sub,+($('#discountAmount').val()||0));$('#cartItems').html(state.cart.length?state.cart.map((x,i)=>`<div class="cart-row"><div><strong>${esc(x.name)}</strong>${x.modifierNames.length?`<div class="small muted">${esc(x.modifierNames.join(', '))}</div>`:''}${x.notes?`<div class="small muted">Catatan: ${esc(x.notes)}</div>`:''}<small>${money(x.base+x.extra)} / item</small></div><div class="qty"><button class="cart-qty" data-i="${i}" data-d="-1">−</button><span>${x.qty}</span><button class="cart-qty" data-i="${i}" data-d="1">+</button><button class="text-btn danger cart-remove" data-i="${i}">×</button></div></div>`).join(''):empty('Belum ada item.'));$('#cartSubtotal').text(money(sub));$('#cartTotal').text(money(Math.max(0,sub-disc)));}
$(document).on('click','.cart-qty',function(){const i=+$(this).data('i');state.cart[i].qty=Math.max(1,state.cart[i].qty+(+$(this).data('d')));renderCart();});$(document).on('click','.cart-remove',function(){state.cart.splice(+$(this).data('i'),1);renderCart();});$('#discountAmount').on('input',renderCart);$('#clearCart').on('click',()=>{state.cart=[];renderCart();});
$('#submitOrderBtn').on('click',function(){if(!state.cart.length)return toast('Keranjang masih kosong.','error');const type=$('#orderType').val();api('orders','create',{order_type:type,table_id:type==='dine_in'?$('#orderTable').val():'',customer_id:$('#orderCustomer').val(),customer_name:$('#customerName').val(),guest_count:$('#guestCount').val(),delivery_address:$('#deliveryAddress').val(),discount_amount:$('#discountAmount').val(),promo_code:$('#promoCode').val(),items:JSON.stringify(state.cart.map(x=>({menu_id:x.menu_id,qty:x.qty,notes:x.notes,modifier_option_ids:x.modifier_option_ids})))},'POST').done(r=>{toast(`Order ${r.data.order_no} dibuat.`);state.cart=[];$('#customerName,#promoCode,#deliveryAddress').val('');$('#discountAmount').val(0);loadPos();});});
function renderActiveOrders(rows){$('#activeOrderList').html(rows.length?rows.map(o=>`<div class="order-card"><div><strong class="mono">${esc(o.order_no)}</strong><div class="small muted">${o.table_number?'Meja '+esc(o.table_number):esc(o.order_type)} · ${esc(o.customer_name||'Guest')} · ${money(o.total)}</div></div><div class="mini-actions">${badge(o.kitchen_status)} ${badge(o.payment_status)}<button class="btn sm outline order-detail" data-id="${o.id}">Detail</button><button class="btn sm danger request-void-order" data-id="${o.id}">Void</button></div></div>`).join(''):empty('Tidak ada order aktif.'));}
$('#refreshActiveOrders').on('click',()=>api('orders','list',{scope:'active'}).done(r=>renderActiveOrders(r.data)));
function orderDetailModal(id){api('orders','detail',{id}).done(r=>{const d=r.data,o=d.order;modal(`<h3>Detail ${esc(o.order_no)}</h3><div class="stack"><div class="order-summary"><div>${badge(o.kitchen_status)} ${badge(o.payment_status)}</div><strong>${money(o.total)}</strong></div><div>${d.items.map(i=>`<label class="order-item-detail"><input type="checkbox" class="split-check" value="${i.id}" ${o.payment_status!=='unpaid'?'disabled':''}><span><strong>${esc(i.item_name)} × ${num(i.quantity)}</strong><small>${i.modifiers.length?esc(i.modifiers.map(m=>m.option_name).join(', ')):'Tanpa modifier'} · ${money(i.subtotal)}</small></span>${i.status!=='voided'?`<button type="button" class="text-btn danger request-void-item" data-id="${i.id}">Void item</button>`:''}</label>`).join('')}</div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Tutup</button>${o.payment_status==='unpaid'?`<button type="button" class="btn outline split-selected" data-order-id="${o.id}">Split Terpilih</button>`:''}</div></div>`,true);});}
$(document).on('click','.order-detail',function(){orderDetailModal(+$(this).data('id'));});$(document).on('click','.split-selected',function(){const ids=$('.split-check:checked').map((_,x)=>+x.value).get();if(!ids.length)return toast('Pilih item untuk split.','error');api('orders','split',{order_id:$(this).data('order-id'),item_ids:JSON.stringify(ids)},'POST').done(r=>{closeModal();toast(`Bill baru ${r.data.order_no} dibuat.`);loadPage(KB.page);});});
function approvalRequestModal(type,entityId,defaults={}){const refund=type==='refund';modal(`<h3>Ajukan ${esc(type.replaceAll('_',' '))}</h3><form id="approvalRequestForm" class="stack"><input type="hidden" name="request_type" value="${esc(type)}"><input type="hidden" name="entity_id" value="${entityId}">${refund?`<div class="form-grid"><label>Jumlah Refund<input class="control" name="refund_amount" type="number" min="1" value="${esc(defaults.amount||'')}" required></label><label>Metode<select class="control" name="refund_method"><option value="cash">Cash</option><option value="qris">QRIS</option><option value="transfer">Transfer</option><option value="card">Card</option><option value="other">Other</option></select></label></div><input type="hidden" name="payment_id" value="${esc(defaults.payment_id||'')}">`:''}<label>Alasan<textarea class="control" name="reason" required></textarea></label><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Kirim Approval</button></div></form>`);}
$(document).on('click','.request-void-order',function(){approvalRequestModal('void_order',+$(this).data('id'));});$(document).on('click','.request-void-item',function(e){e.stopPropagation();approvalRequestModal('void_item',+$(this).data('id'));});$(document).on('submit','#approvalRequestForm',function(e){e.preventDefault();const d=formObj(this);if(d.request_type==='refund')d.payload_json=JSON.stringify({amount:+d.refund_amount,method:d.refund_method,payment_id:d.payment_id||null});api('approvals','request',d,'POST').done(r=>{closeModal();toast(`Approval ${r.data.request_no} dikirim.`);});});

function loadKitchen(){api('kitchen','list',{station:$('#kdsStation').val()||'all'}).done(r=>{const cols={new:[],preparing:[],ready:[],served:[]};r.data.forEach(o=>o.items.forEach(i=>{if(cols[i.status])cols[i.status].push({...i,order_no:o.order_no,table_number:o.table_number,customer_name:o.customer_name,created_at:o.created_at});}));Object.keys(cols).forEach(s=>{$('#kdsCount'+s.charAt(0).toUpperCase()+s.slice(1)).text(cols[s].length);$(`#kds${s.charAt(0).toUpperCase()+s.slice(1)}`).html(cols[s].length?cols[s].map(i=>kdsItem(i)).join(''):empty('Kosong'));});});}
function kdsItem(i){const next={new:['preparing','Mulai'],preparing:['ready','Siap'],ready:['served','Disajikan']}[i.status];const mins=Math.max(0,Math.round((Date.now()-new Date(String(i.created_at).replace(' ','T')).getTime())/60000));return `<div class="ticket"><div class="ticket-top"><strong class="mono">${esc(i.order_no)}</strong><span class="small ${mins>20?'danger-text':'muted'}">${mins}m</span></div><div class="small muted">${i.table_number?'Meja '+esc(i.table_number):esc(i.customer_name||'Guest')} · ${esc(i.preparation_station)}</div><div class="ticket-item"><b>${num(i.quantity)}× ${esc(i.item_name)}</b>${i.notes?`<small>${esc(i.notes)}</small>`:''}</div>${next?`<button class="btn sm primary full kds-next" data-id="${i.item_id}" data-status="${next[0]}">${next[1]}</button>`:''}</div>`;}
$('#kdsStation').on('change',loadKitchen);$(document).on('click','.kds-next',function(){api('kitchen','item_status',{id:$(this).data('id'),status:$(this).data('status')},'POST').done(loadKitchen);});

function loadMenu(){api('menu').done(r=>{const d=r.data;state.menu=d.items;state.categories=d.categories;state.groups=d.groups;state.options=d.options;state.links=d.links;$('#menuBody').html(d.items.map(m=>`<tr><td class="mono">${esc(m.sku)}</td><td><strong>${esc(m.name)}</strong><br><span class="small muted">${esc(m.description||'')}</span></td><td>${esc(m.category_name)}</td><td>${badge(m.preparation_station)}</td><td>${money(m.price)}</td><td>${money(m.cost)}</td><td>${+m.is_available?badge('active'):badge('inactive')}</td><td><div class="mini-actions"><button class="btn sm outline edit-menu" data-id="${m.id}">Edit</button><button class="btn sm outline edit-recipe" data-id="${m.id}">Recipe</button></div></td></tr>`).join(''));$('#modifierList').html(d.groups.length?d.groups.map(g=>{const opts=d.options.filter(o=>+o.group_id===+g.id);return `<div class="modifier-card"><div><strong>${esc(g.name)}</strong><div class="small muted">${opts.map(o=>`${esc(o.name)}${+o.price_delta?' +'+money(o.price_delta):''}`).join(' · ')}</div></div><button class="btn sm outline edit-modifier" data-id="${g.id}">Edit</button></div>`}).join(''):empty('Belum ada modifier.'));});}
function menuModal(m={}){modal(`<h3>${m.id?'Edit':'Tambah'} Menu</h3><form id="menuForm" class="stack"><input type="hidden" name="id" value="${esc(m.id||'')}"><div class="form-grid"><label>SKU<input class="control" name="sku" value="${esc(m.sku||'')}" required></label><label>Nama Menu<input class="control" name="name" value="${esc(m.name||'')}" required></label><label>Kategori<select class="control" name="category_id">${state.categories.map(c=>`<option value="${c.id}" ${+m.category_id===+c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Station<select class="control" name="preparation_station">${['kitchen','bar','dessert','other'].map(s=>`<option value="${s}" ${m.preparation_station===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Harga<input class="control" name="price" type="number" min="0" value="${esc(m.price||0)}" required></label><label>Cost<input class="control" name="cost" type="number" min="0" value="${esc(m.cost||0)}"></label><label>Image URL<input class="control" name="image_url" value="${esc(m.image_url||'')}"></label><label>Status<select class="control" name="is_available"><option value="1" ${+m.is_available!==0?'selected':''}>Available</option><option value="0" ${+m.is_available===0?'selected':''}>Unavailable</option></select></label><label class="span-2">Deskripsi<textarea class="control" name="description">${esc(m.description||'')}</textarea></label></div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`);}
$('#addMenuBtn').on('click',()=>menuModal());$(document).on('click','.edit-menu',function(){menuModal(state.menu.find(x=>+x.id===+$(this).data('id'))||{});});$(document).on('submit','#menuForm',function(e){e.preventDefault();api('menu','save',formObj(this),'POST').done(()=>{closeModal();toast('Menu disimpan.');loadMenu();});});
function modifierModal(g={}){const opts=state.options.filter(o=>+o.group_id===+g.id);modal(`<h3>${g.id?'Edit':'Tambah'} Modifier Group</h3><form id="modifierForm" class="stack"><input type="hidden" name="id" value="${esc(g.id||'')}"><div class="form-grid"><label>Nama<input class="control" name="name" value="${esc(g.name||'')}" required></label><label>Required<select class="control" name="is_required"><option value="0">Tidak</option><option value="1" ${+g.is_required?'selected':''}>Ya</option></select></label><label>Min Pilihan<input class="control" name="min_select" type="number" min="0" value="${esc(g.min_select||0)}"></label><label>Max Pilihan<input class="control" name="max_select" type="number" min="1" value="${esc(g.max_select||1)}"></label></div><div id="modifierOptionRows">${opts.map(o=>modifierOptionRow(o)).join('')}</div><button type="button" class="btn sm outline" id="addModifierOptionRow">+ Option</button><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`);}
function modifierOptionRow(o={}){return `<div class="inline-row modifier-option-row"><input class="control opt-name" placeholder="Nama option" value="${esc(o.name||'')}"><input class="control opt-price" type="number" placeholder="Harga +" value="${esc(o.price_delta||0)}"><button type="button" class="text-btn danger remove-row">×</button></div>`;}
$('#addModifierBtn').on('click',()=>modifierModal());$(document).on('click','.edit-modifier',function(){modifierModal(state.groups.find(x=>+x.id===+$(this).data('id'))||{});});$(document).on('click','#addModifierOptionRow',()=>$('#modifierOptionRows').append(modifierOptionRow()));$(document).on('click','.remove-row',function(){$(this).closest('.inline-row').remove();});$(document).on('submit','#modifierForm',function(e){e.preventDefault();const d=formObj(this),opts=[];$('.modifier-option-row').each(function(){opts.push({name:$(this).find('.opt-name').val(),price_delta:$(this).find('.opt-price').val()})});d.options=JSON.stringify(opts);api('menu','modifier_save',d,'POST').done(()=>{closeModal();toast('Modifier disimpan.');loadMenu();});});
$(document).on('click','.edit-recipe',function(){const mid=+$(this).data('id'),m=state.menu.find(x=>+x.id===mid);api('menu','recipe',{menu_id:mid}).done(r=>{const d=r.data;modal(`<h3>Recipe & Modifier · ${esc(m?.name||'Menu')}</h3><form id="recipeForm" class="stack"><input type="hidden" name="menu_item_id" value="${mid}"><div id="recipeRows">${d.recipe.map(x=>recipeRow(d.ingredients,x)).join('')}</div><button type="button" class="btn sm outline" id="addRecipeRow">+ Bahan</button><div><strong>Modifier Group untuk menu ini</strong><div class="check-grid">${d.groups.map(g=>`<label><input type="checkbox" class="recipe-mod-group" value="${g.id}" ${d.modifier_group_ids.includes(+g.id)?'checked':''}> ${esc(g.name)}</label>`).join('')}</div></div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan Recipe</button></div></form>`,true);$('#recipeForm').data('ingredients',d.ingredients);});});
function recipeRow(ingredients,r={}){return `<div class="inline-row recipe-row"><select class="control rec-ing">${ingredients.map(i=>`<option value="${i.id}" ${+r.ingredient_id===+i.id?'selected':''}>${esc(i.name)} (${esc(i.unit)})</option>`).join('')}</select><input class="control rec-qty" type="number" step="0.001" min="0.001" value="${esc(r.quantity||1)}"><button type="button" class="text-btn danger remove-row">×</button></div>`;}
$(document).on('click','#addRecipeRow',function(){const ings=$('#recipeForm').data('ingredients')||[];$('#recipeRows').append(recipeRow(ings));});$(document).on('submit','#recipeForm',function(e){e.preventDefault();const rows=[];$('.recipe-row').each(function(){rows.push({ingredient_id:$(this).find('.rec-ing').val(),quantity:$(this).find('.rec-qty').val()})});api('menu','recipe_save',{menu_item_id:$(this).find('[name=menu_item_id]').val(),recipe:JSON.stringify(rows),modifier_group_ids:JSON.stringify($('.recipe-mod-group:checked').map((_,x)=>+x.value).get())},'POST').done(()=>{closeModal();toast('Recipe diperbarui.');});});

function loadInventory(){api('inventory').done(r=>{state.ingredients=r.data.items;$('#inventoryBody').html(state.ingredients.map(i=>`<tr><td><strong>${esc(i.name)}</strong><br><span class="small mono muted">${esc(i.sku)}</span></td><td>${num(i.current_stock,3)} ${esc(i.unit)}</td><td>${num(i.min_stock,3)} ${esc(i.unit)}</td><td>${money(i.cost_per_unit)}</td><td>${+i.low_stock?'<span class="badge red">Low Stock</span>':'<span class="badge green">Aman</span>'}</td><td><button class="btn sm outline edit-ingredient" data-id="${i.id}">Edit</button></td></tr>`).join(''));$('#movementList').html(r.data.movements.length?r.data.movements.map(m=>`<div class="timeline-row"><strong>${esc(m.ingredient_name)} · ${esc(m.movement_type)}</strong><span class="small muted">${num(m.quantity,3)} ${esc(m.unit)} · balance ${num(m.balance_after,3)}</span><br><span class="small muted">${dt(m.created_at)} · ${esc(m.user_name||'System')}</span></div>`).join(''):empty('Belum ada pergerakan.'));});}
function ingredientModal(i={}){modal(`<h3>${i.id?'Edit':'Tambah'} Bahan</h3><form id="ingredientForm" class="stack"><input type="hidden" name="id" value="${esc(i.id||'')}"><div class="form-grid"><label>SKU<input class="control" name="sku" value="${esc(i.sku||'')}" required></label><label>Nama<input class="control" name="name" value="${esc(i.name||'')}" required></label><label>Unit<input class="control" name="unit" value="${esc(i.unit||'gram')}" required></label>${!i.id?`<label>Stok Awal<input class="control" type="number" step="0.001" name="current_stock" value="0"></label>`:''}<label>Min. Stock<input class="control" type="number" step="0.001" name="min_stock" value="${esc(i.min_stock||0)}"></label><label>Cost / Unit<input class="control" type="number" step="0.0001" name="cost_per_unit" value="${esc(i.cost_per_unit||0)}"></label><label>Status<select class="control" name="status"><option value="active">active</option><option value="inactive" ${i.status==='inactive'?'selected':''}>inactive</option></select></label></div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`);}
$('#addIngredientBtn').on('click',()=>ingredientModal());$(document).on('click','.edit-ingredient',function(){ingredientModal(state.ingredients.find(x=>+x.id===+$(this).data('id'))||{});});$(document).on('submit','#ingredientForm',function(e){e.preventDefault();api('inventory','save',formObj(this),'POST').done(()=>{closeModal();toast('Bahan disimpan.');loadInventory();});});$('#adjustStockBtn').on('click',()=>{modal(`<h3>Pergerakan Stok</h3><form id="stockForm" class="stack"><label>Bahan<select class="control" name="ingredient_id">${state.ingredients.map(i=>`<option value="${i.id}">${esc(i.name)} · ${num(i.current_stock,3)} ${esc(i.unit)}</option>`).join('')}</select></label><div class="form-grid"><label>Tipe<select class="control" name="movement_type"><option value="in">Stock In</option><option value="out">Stock Out</option><option value="waste">Waste</option><option value="adjustment">Set Saldo Aktual</option></select></label><label>Jumlah<input class="control" type="number" step="0.001" min="0.001" name="quantity" required></label></div><label>Catatan<input class="control" name="notes"></label><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`);});$(document).on('submit','#stockForm',function(e){e.preventDefault();api('inventory','adjust',formObj(this),'POST').done(()=>{closeModal();toast('Stok diperbarui.');loadInventory();});});

function loadPurchasing(){api('purchasing').done(r=>{state.suppliers=r.data.suppliers;state.ingredients=r.data.ingredients;$('#poBody').html(r.data.orders.length?r.data.orders.map(p=>`<tr><td class="mono">${esc(p.po_no)}</td><td>${esc(p.supplier_name)}</td><td>${esc(p.order_date)}</td><td>${money(p.subtotal)}</td><td>${badge(p.status)}</td><td>${p.status==='ordered'||p.status==='partial'?`<button class="btn sm success receive-po" data-id="${p.id}">Terima</button>`:''}</td></tr>`).join(''):`<tr><td colspan="6">${empty('Belum ada PO.')}</td></tr>`);$('#supplierBody').html(state.suppliers.map(s=>`<tr><td><strong>${esc(s.name)}</strong><br><span class="small muted">${esc(s.contact_person||'')}</span></td><td>${esc(s.phone||'-')}<br><span class="small muted">${esc(s.email||'')}</span></td><td>${badge(s.status)}</td><td><button class="btn sm outline edit-supplier" data-id="${s.id}">Edit</button></td></tr>`).join(''));});}
function supplierModal(s={}){modal(`<h3>${s.id?'Edit':'Tambah'} Supplier</h3><form id="supplierForm" class="stack"><input type="hidden" name="id" value="${esc(s.id||'')}"><div class="form-grid"><label>Nama<input class="control" name="name" value="${esc(s.name||'')}" required></label><label>Contact Person<input class="control" name="contact_person" value="${esc(s.contact_person||'')}"></label><label>Phone<input class="control" name="phone" value="${esc(s.phone||'')}"></label><label>Email<input class="control" type="email" name="email" value="${esc(s.email||'')}"></label><label>Status<select class="control" name="status"><option value="active">active</option><option value="inactive" ${s.status==='inactive'?'selected':''}>inactive</option></select></label><label class="span-2">Alamat<textarea class="control" name="address">${esc(s.address||'')}</textarea></label></div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`);}
$('#addSupplierBtn').on('click',()=>supplierModal());$(document).on('click','.edit-supplier',function(){supplierModal(state.suppliers.find(x=>+x.id===+$(this).data('id'))||{});});$(document).on('submit','#supplierForm',function(e){e.preventDefault();api('purchasing','supplier_save',formObj(this),'POST').done(()=>{closeModal();toast('Supplier disimpan.');loadPurchasing();});});
function poRow(){return `<div class="inline-row po-row"><select class="control po-ing">${state.ingredients.map(i=>`<option value="${i.id}" data-cost="${i.cost_per_unit}">${esc(i.name)} (${esc(i.unit)})</option>`).join('')}</select><input class="control po-qty" type="number" step="0.001" min="0.001" placeholder="Qty"><input class="control po-cost" type="number" step="0.0001" min="0" placeholder="Unit cost"><button type="button" class="text-btn danger remove-row">×</button></div>`;}
$('#addPoBtn').on('click',()=>modal(`<h3>Purchase Order Baru</h3><form id="poForm" class="stack"><div class="form-grid"><label>Supplier<select class="control" name="supplier_id">${state.suppliers.filter(s=>s.status==='active').map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>Tanggal<input class="control" type="date" name="order_date" value="${new Date().toISOString().slice(0,10)}"></label><label>Expected Date<input class="control" type="date" name="expected_date"></label><label class="span-2">Catatan<input class="control" name="notes"></label></div><div id="poRows">${poRow()}</div><button type="button" class="btn sm outline" id="addPoRow">+ Item</button><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Buat PO</button></div></form>`,true));$(document).on('click','#addPoRow',()=>$('#poRows').append(poRow()));$(document).on('change','.po-ing',function(){$(this).closest('.po-row').find('.po-cost').val(this.options[this.selectedIndex].dataset.cost||0);});$(document).on('submit','#poForm',function(e){e.preventDefault();const d=formObj(this),items=[];$('.po-row').each(function(){items.push({ingredient_id:$(this).find('.po-ing').val(),quantity:$(this).find('.po-qty').val(),unit_cost:$(this).find('.po-cost').val()})});d.items=JSON.stringify(items);api('purchasing','save',d,'POST').done(r=>{closeModal();toast(`PO ${r.data.po_no} dibuat.`);loadPurchasing();});});$(document).on('click','.receive-po',function(){if(!confirm('Terima seluruh sisa item PO dan tambah ke stok?'))return;api('purchasing','receive',{id:$(this).data('id')},'POST').done(()=>{toast('PO diterima dan stok diperbarui.');loadPurchasing();});});

function loadShifts(){api('shifts').done(r=>{const d=r.data,c=d.current,s=d.summary;$('#shiftActionBtn').text(c?'Tutup Shift':'Buka Shift').toggleClass('danger',!!c).toggleClass('primary',!c);$('#cashMovementBtn').prop('disabled',!c);$('#shiftCurrent').html(c?`<div class="stat-grid"><div class="stat-card"><div class="label">Opening Cash</div><div class="value">${money(c.opening_cash)}</div></div><div class="stat-card"><div class="label">Cash Sales</div><div class="value">${money(s.cashSales)}</div></div><div class="stat-card"><div class="label">Cash In / Out</div><div class="value">${money(s.cashIn-s.cashOut)}</div></div><div class="stat-card"><div class="label">Expected Cash</div><div class="value">${money(s.expected)}</div></div></div>`:empty('Belum ada shift aktif.'));$('#cashMovementList').html(d.movements.length?d.movements.map(m=>`<div class="rank-row"><span>${badge(m.type)} ${esc(m.category||'Cash movement')}<small class="muted"> · ${dt(m.created_at)}</small></span><strong>${money(m.amount)}</strong></div>`).join(''):empty('Belum ada cash movement.'));$('#shiftHistory').html(d.history.length?d.history.map(h=>`<tr><td>${esc(h.user_name)}</td><td>${dt(h.opened_at)}</td><td>${dt(h.closed_at)}</td><td>${money(h.expected_cash)}</td><td>${money(h.closing_cash_actual)}</td><td>${h.difference_amount===null?'-':money(h.difference_amount)}</td></tr>`).join(''):`<tr><td colspan="6">${empty('Belum ada histori.')}</td></tr>`);});}
$('#shiftActionBtn').on('click',function(){api('shifts').done(r=>{const c=r.data.current,s=r.data.summary;if(!c)modal(`<h3>Buka Shift</h3><form id="openShiftForm" class="stack"><label>Opening Cash<input class="control" type="number" name="opening_cash" min="0" value="0" required></label><label>Catatan<input class="control" name="notes"></label><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Buka Shift</button></div></form>`);else modal(`<h3>Tutup Shift</h3><div class="alert">Expected cash: <strong>${money(s.expected)}</strong></div><form id="closeShiftForm" class="stack"><label>Closing Cash Aktual<input class="control" type="number" name="closing_cash_actual" min="0" required></label><label>Catatan<textarea class="control" name="notes"></textarea></label><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn danger">Tutup Shift</button></div></form>`);});});$(document).on('submit','#openShiftForm',function(e){e.preventDefault();api('shifts','open',formObj(this),'POST').done(()=>{closeModal();toast('Shift dibuka.');loadShifts();});});$(document).on('submit','#closeShiftForm',function(e){e.preventDefault();api('shifts','close',formObj(this),'POST').done(r=>{closeModal();toast(`Shift ditutup. Selisih ${money(r.data.difference)}.`);loadShifts();});});$('#cashMovementBtn').on('click',()=>modal(`<h3>Cash In / Out</h3><form id="cashMovementForm" class="stack"><div class="form-grid"><label>Tipe<select class="control" name="type"><option value="in">Cash In</option><option value="out">Cash Out</option></select></label><label>Jumlah<input class="control" type="number" min="1" name="amount" required></label></div><label>Kategori<input class="control" name="category" placeholder="Petty cash, change fund, dll"></label><label>Catatan<input class="control" name="notes"></label><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`));$(document).on('submit','#cashMovementForm',function(e){e.preventDefault();api('shifts','movement',formObj(this),'POST').done(()=>{closeModal();toast('Cash movement dicatat.');loadShifts();});});

function loadPayments(){api('payments').done(r=>{const d=r.data;$('#unpaidList').html(d.unpaid.length?d.unpaid.map(o=>`<div class="panel soft-card"><div class="order-card"><div><strong class="mono">${esc(o.order_no)}</strong><div class="small muted">${o.table_number?'Meja '+esc(o.table_number):esc(o.order_type)} · ${esc(o.customer_name||'Guest')}</div></div><div style="text-align:right"><strong>${money(o.remaining_amount)}</strong><div class="small muted">dari ${money(o.total)}</div></div></div><div class="mini-actions">${badge(o.payment_status)}<button class="btn sm primary pay-order" data-id="${o.id}" data-total="${o.remaining_amount}" data-no="${esc(o.order_no)}">Bayar</button><button class="btn sm outline payment-order-detail" data-id="${o.id}">Detail / Split</button></div></div>`).join(''):empty('Semua order sudah lunas.'));$('#paymentHistory').html(d.history.length?d.history.map(p=>`<tr><td class="mono">${esc(p.payment_no)}</td><td>${esc(p.order_no)}</td><td>${badge(p.method)}</td><td>${money(p.amount)}</td><td>${dt(p.paid_at)}</td><td><div class="mini-actions"><a class="btn sm outline" target="_blank" href="receipt.php?id=${p.order_id}">Struk</a><button class="btn sm danger request-refund" data-order-id="${p.order_id}" data-payment-id="${p.id}" data-amount="${p.amount}">Refund</button></div></td></tr>`).join(''):`<tr><td colspan="6">${empty('Belum ada pembayaran.')}</td></tr>`);$('#refundHistory').html(d.refunds.length?d.refunds.map(x=>`<tr><td class="mono">${esc(x.refund_no)}</td><td>${esc(x.order_no)}</td><td>${badge(x.method)}</td><td>${money(x.amount)}</td><td>${esc(x.reason)}</td><td>${dt(x.processed_at)}</td></tr>`).join(''):`<tr><td colspan="6">${empty('Belum ada refund.')}</td></tr>`);});}
$(document).on('click','.pay-order',function(){const id=$(this).data('id'),total=+$(this).data('total'),no=$(this).data('no');modal(`<h3>Pembayaran ${esc(no)}</h3><form id="paymentForm" class="stack"><input type="hidden" name="order_id" value="${id}"><label>Jumlah<input class="control" type="number" min="1" name="amount" value="${total}" required></label><label>Metode<select class="control" name="method"><option value="cash">Cash</option><option value="qris">QRIS</option><option value="transfer">Transfer</option><option value="card">Card</option><option value="other">Other</option></select></label><label>Reference No.<input class="control" name="reference_no"></label><label>Catatan<input class="control" name="notes"></label><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Konfirmasi Pembayaran</button></div></form>`);});$(document).on('submit','#paymentForm',function(e){e.preventDefault();api('payments','create',formObj(this),'POST').done(r=>{closeModal();toast(`Pembayaran ${r.data.payment_no} berhasil.`);loadPayments();});});$(document).on('click','.payment-order-detail',function(){orderDetailModal(+$(this).data('id'));});$(document).on('click','.request-refund',function(){approvalRequestModal('refund',+$(this).data('order-id'),{payment_id:$(this).data('payment-id'),amount:$(this).data('amount')});});

function loadApprovals(){api('approvals').done(r=>{$('#approvalBody').html(r.data.length?r.data.map(a=>`<tr><td class="mono">${esc(a.request_no)}</td><td>${badge(a.request_type)}</td><td>${esc(a.entity_type)} #${a.entity_id}</td><td>${esc(a.reason)}</td><td>${esc(a.requested_by_name)}</td><td>${badge(a.status)}</td><td>${dt(a.created_at)}</td><td>${a.status==='pending'?`<div class="mini-actions"><button class="btn sm success approval-decision" data-id="${a.id}" data-decision="approved">Approve</button><button class="btn sm danger approval-decision" data-id="${a.id}" data-decision="rejected">Reject</button></div>`:''}</td></tr>`).join(''):`<tr><td colspan="8">${empty('Belum ada approval request.')}</td></tr>`);});}
$(document).on('click','.approval-decision',function(){const id=$(this).data('id'),decision=$(this).data('decision');modal(`<h3>${decision==='approved'?'Approve':'Reject'} Request</h3><form id="approvalDecisionForm" class="stack"><input type="hidden" name="id" value="${id}"><input type="hidden" name="decision" value="${decision}"><label>Catatan keputusan<textarea class="control" name="decision_notes"></textarea></label><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn ${decision==='approved'?'success':'danger'}">Konfirmasi</button></div></form>`);});$(document).on('submit','#approvalDecisionForm',function(e){e.preventDefault();api('approvals','decide',formObj(this),'POST').done(()=>{closeModal();toast('Approval diproses.');loadApprovals();});});

function loadPromotions(){api('promotions').done(r=>{state.promotions=r.data;$('#promoBody').html(state.promotions.length?state.promotions.map(p=>`<tr><td class="mono">${esc(p.code)}</td><td><strong>${esc(p.name)}</strong></td><td>${p.discount_type==='percent'?num(p.discount_value)+'%':money(p.discount_value)}</td><td>${money(p.min_spend)}</td><td>${dt(p.starts_at)} – ${dt(p.ends_at)}</td><td>${+p.is_active?badge('active'):badge('inactive')}</td><td><button class="btn sm outline edit-promo" data-id="${p.id}">Edit</button></td></tr>`).join(''):`<tr><td colspan="7">${empty('Belum ada promo.')}</td></tr>`);});}
function promoModal(p={}){modal(`<h3>${p.id?'Edit':'Tambah'} Promo</h3><form id="promoForm" class="stack"><input type="hidden" name="id" value="${esc(p.id||'')}"><div class="form-grid"><label>Kode<input class="control" name="code" value="${esc(p.code||'')}" required></label><label>Nama<input class="control" name="name" value="${esc(p.name||'')}" required></label><label>Tipe<select class="control" name="discount_type"><option value="percent" ${p.discount_type!=='fixed'?'selected':''}>Percent</option><option value="fixed" ${p.discount_type==='fixed'?'selected':''}>Fixed</option></select></label><label>Nilai<input class="control" type="number" min="0" step="0.01" name="discount_value" value="${esc(p.discount_value||0)}"></label><label>Minimum Spend<input class="control" type="number" min="0" name="min_spend" value="${esc(p.min_spend||0)}"></label><label>Max Discount<input class="control" type="number" min="0" name="max_discount" value="${esc(p.max_discount||'')}"></label><label>Mulai<input class="control" type="datetime-local" name="starts_at" value="${p.starts_at?esc(String(p.starts_at).replace(' ','T').slice(0,16)):''}"></label><label>Berakhir<input class="control" type="datetime-local" name="ends_at" value="${p.ends_at?esc(String(p.ends_at).replace(' ','T').slice(0,16)):''}"></label><label>Status<select class="control" name="is_active"><option value="1">Aktif</option><option value="0" ${+p.is_active===0?'selected':''}>Nonaktif</option></select></label></div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`);}
$('#addPromoBtn').on('click',()=>promoModal());$(document).on('click','.edit-promo',function(){promoModal(state.promotions.find(x=>+x.id===+$(this).data('id'))||{});});$(document).on('submit','#promoForm',function(e){e.preventDefault();api('promotions','save',formObj(this),'POST').done(()=>{closeModal();toast('Promo disimpan.');loadPromotions();});});

function loadReports(){const from=$('#reportFrom').val()||'',to=$('#reportTo').val()||'';api('reports','list',{from,to}).done(r=>{const d=r.data;const grossProfit=d.revenue-d.cogs;$('#reportStats').html([['Net Sales',money(d.revenue)],['Order',d.orders],['Avg. Order',money(d.orders?d.revenue/d.orders:0)],['Discount',money(d.discounts)],['Refund',money(d.refunds)],['COGS',money(d.cogs)],['Gross Profit',money(grossProfit)],['Waste Qty',num(d.waste,3)]].map(c=>`<div class="stat-card"><div class="label">${c[0]}</div><div class="value">${c[1]}</div></div>`).join(''));renderBars('#reportDaily',d.daily.map(x=>({label:new Date(x.d+'T00:00:00').toLocaleDateString('id-ID',{day:'2-digit',month:'short'}),value:+x.revenue})));$('#reportMethods').html(d.byMethod.length?d.byMethod.map(x=>`<div class="rank-row"><span>${esc(x.method)} <small class="muted">(${x.count} pembayaran)</small></span><strong>${money(x.total)}</strong></div>`).join(''):empty('Tidak ada pembayaran.'));$('#reportTopItems').html(d.topItems.length?d.topItems.map(x=>`<tr><td>${esc(x.item_name)}</td><td>${num(x.qty)}</td><td>${money(x.sales)}</td></tr>`).join(''):`<tr><td colspan="3">${empty('Tidak ada data.')}</td></tr>`);$('#reportHourly').html(d.hourly.length?d.hourly.map(x=>`<div class="rank-row"><span>${String(x.hour).padStart(2,'0')}:00 <small class="muted">(${x.orders} order)</small></span><strong>${money(x.sales)}</strong></div>`).join(''):empty('Tidak ada data.'));$('#exportReport').attr('href',`report_export.php?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`);});}
$('#runReport').on('click',loadReports);

function loadSettings(){api('settings').done(r=>{Object.entries(r.data).forEach(([k,v])=>{$(`#settingsForm [name="${k}"]`).val(v)});});}$(document).on('submit','#settingsForm',function(e){e.preventDefault();api('settings','save',formObj(this),'POST').done(()=>toast('Pengaturan disimpan.'));});


function loadAudits(){api('audits').done(r=>{$('#auditBody').html(r.data.length?r.data.map(a=>`<tr><td>${dt(a.created_at)}</td><td>${esc(a.user_name||'System')}<br><span class="small muted">${esc(a.user_email||'')}</span></td><td class="mono">${esc(a.action)}</td><td>${esc(a.entity_type||'-')} ${a.entity_id?'#'+a.entity_id:''}</td><td><code class="payload-code">${esc(a.payload_json||'')}</code></td><td>${esc(a.ip_address||'-')}</td></tr>`).join(''):`<tr><td colspan="6">${empty('Belum ada audit log.')}</td></tr>`);});}
function loadUsers(){api('users').done(r=>{state.users=r.data.users;state.roles=r.data.roles;$('#userBody').html(state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.email)}</td><td>${badge(u.role_slug)}</td><td>${badge(u.status)}</td><td>${dt(u.last_login_at)}</td><td><button class="btn sm outline edit-user" data-id="${u.id}">Edit</button></td></tr>`).join(''));});}
function userModal(u={}){modal(`<h3>${u.id?'Edit':'Tambah'} User</h3><form id="userForm" class="stack"><input type="hidden" name="id" value="${esc(u.id||'')}"><div class="form-grid"><label>Nama<input class="control" name="name" value="${esc(u.name||'')}" required></label><label>Email<input class="control" type="email" name="email" value="${esc(u.email||'')}" required></label><label>Role<select class="control" name="role_id">${state.roles.map(r=>`<option value="${r.id}" ${+u.role_id===+r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label>Status<select class="control" name="status"><option value="active" ${u.status!=='inactive'?'selected':''}>active</option><option value="inactive" ${u.status==='inactive'?'selected':''}>inactive</option></select></label><label>Telepon<input class="control" name="phone" value="${esc(u.phone||'')}"></label><label>Password ${u.id?'<span class="small muted">(kosongkan jika tidak diubah)</span>':''}<input class="control" type="password" name="password" ${u.id?'':'required minlength="8"'}></label></div><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Simpan</button></div></form>`);}
$('#addUserBtn').on('click',()=>userModal());$(document).on('click','.edit-user',function(){userModal(state.users.find(x=>+x.id===+$(this).data('id'))||{});});$(document).on('submit','#userForm',function(e){e.preventDefault();api('users','save',formObj(this),'POST').done(()=>{closeModal();toast('User disimpan.');loadUsers();});});

function loadPage(p){({dashboard:loadDashboard,tables:loadTables,reservations:loadReservations,customers:loadCustomers,pos:loadPos,kitchen:loadKitchen,menu:loadMenu,inventory:loadInventory,purchasing:loadPurchasing,shifts:loadShifts,payments:loadPayments,approvals:loadApprovals,promotions:loadPromotions,reports:loadReports,audits:loadAudits,settings:loadSettings,users:loadUsers}[p]||function(){})();}
loadPage(KB.page);if(KB.page==='kitchen')setInterval(loadKitchen,10000);if(KB.page==='dashboard')setInterval(loadDashboard,60000);
})(jQuery);
